import * as T from 'three';
export function floorRoute(floor){const path=[[0,.175,5.6],[0,.31,2.9],[-3.7,.31,2.9],[-3.7,.31,3.2]];
for(let f=0;f<floor-1;f++){const x=f%2?-2.1:-3.7;path.push([x,.31+f*3.2,f%2?-2.65:3.2]);for(let n=0;n<16;n++)path.push([x,.31+f*3.2+(n+1)*.2,f%2?-2.25+n*.35:3-n*.35]);const y=.31+(f+1)*3.2;path.push([x,y,f%2?3.2:-2.65]);if(f<floor-2)path.push([f%2?-3.7:-2.1,y,f%2?3.2:-2.65]);}
const y=.31+(floor-1)*3.2;if(floor>1)path.push([-1,y,(floor-1)%2?-2.65:3.2]);path.push([-1,y,2.3],[1.2,y,2.3]);return path;}
export function sampleRoute(route,d){for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],len=a.distanceTo(b);if(d<=len||i===route.length-1)return {position:a.clone().lerp(b,Math.min(1,Math.max(0,d)/(len||1))),heading:Math.atan2(-(b.x-a.x),-(b.z-a.z)),index:i};d-=len}return {position:route[0].clone(),heading:0,index:0};}
export function retreatRoute(a){return a.search?[a.root.position.clone(),...a.search.route.slice(0,a.search.index).reverse().map(p=>p.clone())]:[a.root.position.clone(),new T.Vector3(a.root.position.x,.175,5.6),new T.Vector3(0,.175,5.6)];}
export function updateInteriorSearch(a,u,dt,t,running){
if(!a.search||a.search.id!==u.searchId){const route=retreatRoute(a);const entry=new T.Vector3(0,.175,5.6);route.push(entry);if(u.searchFloor){const y=.31+(u.searchFloor-1)*3.2;route.push(...floorRoute(u.searchFloor).map(p=>new T.Vector3(...p)));const arrival=route.length-1;route.push(...[[3,y,2.3],[2.825,y,.2],[2.825,y,-2.5],[4.2,y,-2.5],[2.825,y,-2.5],[2.825,y,.2],[1.2,y,2.3]].map(p=>new T.Vector3(...p)));a.search={id:u.searchId,route,distance:0,index:1,arrival,reported:false};}else a.search={id:u.searchId,route,distance:0,index:1,arrival:route.length-1,reported:false};a.search.length=route.slice(1).reduce((sum,p,i)=>sum+p.distanceTo(route[i]),0);a.route=[];}
const s=a.search;if(running)s.distance=Math.min(s.length,s.distance+dt*.9);const lead=sampleRoute(s.route,s.distance);a.root.position.copy(lead.position);a.root.rotation.y=0;s.index=lead.index;
a.people.forEach((p,j)=>{const at=sampleRoute(s.route,Math.max(0,s.distance-j*.8));p.body.position.copy(at.position).sub(a.root.position);p.body.rotation.set(0,at.heading,0);const stride=s.distance<s.length?Math.sin(t*7+j)*.35:0;p.legs[0].rotation.x=stride;p.legs[1].rotation.x=-stride;p.arms[0].rotation.x=-stride;p.arms[1].rotation.x=1.1;p.beam.visible=!!u.searchFloor;p.nozzle.visible=false;p.body.updateWorldMatrix(true,true);const bottom=Math.min(...p.boots.map(b=>new T.Box3().setFromObject(b).min.y));p.body.position.y+=at.position.y-bottom;});a.ring.visible=false;a.hose.visible=false;a.water.visible=false;
if(s.distance>=s.length&&!s.reported){s.reported=true;return 'complete'}if(lead.index>s.arrival&&u.status==='移動中')return 'arrived';return null;
}
